def transform(grid):
    h, w = len(grid), len(grid[0])
    for j in range(w):
        if all(row[j] == 0 for row in grid):
            left = [row[:j] for row in grid]
            right = [row[j + 1:] for row in grid]
            color = next(iter(set(x for row in left for x in row) & set(x for row in right for x in row)))
            return [[3 if a == b == color else color for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
    for i, row in enumerate(grid):
        if all(x == 0 for x in row):
            top, bottom = grid[:i], grid[i + 1:]
            color = next(iter(set(x for r in top for x in r) & set(x for r in bottom for x in r)))
            return [[3 if a == b == color else color for a, b in zip(ra, rb)] for ra, rb in zip(top, bottom)]
    raise ValueError('separator not found')
